from flaxon import Flaxon

app = Flaxon("hello-api", debug=True)

@app.get("/")
async def home():
    return {"message": "Hello from Flaxon"}

@app.get("/users/<int:user_id>")
async def user(user_id: int):
    return {"id": user_id}

from pathlib import Path
from flaxon import Flaxon, Request

app = Flaxon("counter", debug=True)
app.use_teloce(project_root=Path(__file__).parent, ui_dir="ui", title="Counter")

@app.get("/")
async def home(request: Request):
    return await request.compile("app.html")

@app.get("/api/hello")
async def hello():
    return {"message": "Hello from the API"}

